/**
 * "Our coaches" content. Names and cards are placeholders for the pitch demo; photos are in
 * ../replace-image.
 * Positions (where each cutout sits on the portrait, hover outlines) come from teamLayout.json,
 * generated by scripts/build-team.py; re-run it if the photos change.
 */
import { CLUB } from '../../club'
import layout from './teamLayout.json'

export type CoachId = keyof typeof layout.people

export interface Coach {
  id: CoachId
  name: string
  /** The small pill on the client's card. */
  badge: string
  role: string
  qualifications: readonly string[]
  bio: string
  specialization: string
  /** Which side of the person the card opens on (towards the open space in the picture). */
  side: 'left' | 'right'
}

